import { useEffect, useState } from "react";
import MenuGrid from "./MenuGrid";
import Cart from "./Cart";
import UserOrders from "./UserOrders";
import { useAuth } from "../../context/AuthContext";
import "../../styles/canteen-ui.css";



export default function UserPanel() {
  const { user, logout } = useAuth();
  const [cart, setCart] = useState([]);
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);

  // ✅ Quantity-based add
  const addToCart = item => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);

      if (existing) {
        return prev.map(i =>
          i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i
        );
      }

      return [...prev, { ...item, quantity: 1 }];
    });
  };

  // ✅ Quantity-based remove
  const removeFromCart = id => {
    setCart(prev =>
      prev
        .map(i =>
          i.id === id ? { ...i, quantity: i.quantity - 1 } : i
        )
        .filter(i => i.quantity > 0)
    );
  };

  const placeOrder = async () => {
    if (cart.length === 0) return;

    const grouped = {};
    cart.forEach(i => {
      grouped[i.id] = grouped[i.id]
        ? { ...grouped[i.id], quantity: grouped[i.id].quantity + 1 }
        : { ...i, quantity: 1 };
    });

    const items = Object.values(grouped);
    const total = items.reduce((s, i) => s + i.price * i.quantity, 0);
    const order_id = Date.now();

    // local update (instant UI)
    setOrders(prev => [
      { order_id, items, total, status: "Pending" },
      ...prev
    ]);

    await fetch("http://127.0.0.1:8000/api/orders/create/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        order_id,
        user: user.username,
        items,
        total
      })
    });

    setCart([]);
  };

  // 🔄 REAL-TIME USER ORDER SYNC
  useEffect(() => {
    const interval = setInterval(() => {
      fetch(`http://127.0.0.1:8000/api/orders/?user=${user.username}`)
        .then(res => res.json())
        .then(setOrders);
    }, 2000); // every 2 seconds

    return () => clearInterval(interval);
  }, [user.username]);

  return (
    <div>
      <header>
        <h2>Welcome {user.username}</h2>
        <button onClick={logout}>Logout</button>
      </header>

      <MenuGrid addToCart={addToCart} />
      <Cart cart={cart} removeFromCart={removeFromCart} placeOrder={placeOrder} />
      <UserOrders orders={orders} />
    </div>
  );
}
